'use strict';
const NEED_REVIEW_KEY='antar-needs-reviews-v1';
let needReviews=[];try{const r=JSON.parse(localStorage.getItem(NEED_REVIEW_KEY)||'[]');if(Array.isArray(r))needReviews=r.filter(x=>x&&typeof x.fingerprint==='string'&&['fits','corrected'].includes(x.choice)).slice(-100);}catch{}
let needScope='90',correctingNeed='',memoryMood='current',memoryNeed='current',memorySituation='any',memoryAlternatives=false;
let logFilters={mood:'any',need:'any',situation:'any',outcome:'any',q:'',from:'',to:''},historyLimit=30,historyEvidenceIds=null;
function needLabel(id){const n=careNeeds.find(x=>x[0]===id);return n?n[1]:id==='unsure'||!id?'Not sure / not recorded':id;}
function needOptions(value,any=true){return `${any?`<option value="any" ${value==='any'?'selected':''}>Any need</option>`:'<option value="">Not sure / skip</option>'}${careNeeds.map(([id,label,h])=>`<option value="${id}" ${value===id?'selected':''}>${esc(label)}${bilingual?' · '+esc(h):''}</option>`).join('')}`}
function pastProfile(){return{moods:memoryMood==='current'?selected:memoryMood==='any'?[]:[memoryMood],need:memoryNeed==='current'?feltNeed:memoryNeed==='any'?'':memoryNeed,situation:memorySituation,intensity};}
const memoryGroupCache=new Map();
function memoryResults(compact=false){const profile=compact?{moods:selected,need:feltNeed,situation:'any',intensity}:pastProfile();return AntarMemory.similarActions(checkins,profile).map(g=>({...g,filterNeed:profile.need}));}
function memoryCard(group){memoryGroupCache.set(group.id,group);const excerpt=group.excerptId&&excerptBank?.find(e=>e.id===group.excerptId);const title=excerpt?.heading||group.activityDetail||nameFor(activityChoices,group.activity);const reasons=[...group.matchedMoods.map(id=>moodData.find(m=>m.id===id)?.name||id),...(group.needMatched?[needLabel(group.filterNeed)]:[])];let action='';if(group.activity==='reset')action=button('Try the quiet reset','start-reset','secondary');else if(group.activity==='story')action=button('Choose a story','go-play','secondary');else if(group.activity==='reflection')action=`<a class="download-book" href="${group.excerptId?'#excerpt/'+encodeURIComponent(group.excerptId):'#passages'}">Open the reading</a>`;else action=`<button class="secondary" data-keep-memory="${esc(group.id)}">Keep this idea in my anchors</button>`;return `<div class="memory-card"><p class="small">${group.similar?'From similar saved moments':'From your previous rated moments'}</p><h3>${esc(title)}</h3><p>You marked this helpful in <strong>${group.helped} of ${group.rated}</strong> rated ${group.rated===1?'entry':'entries'}${group.similar?'.':', without a feeling/need comparison selected.'}</p><p class="small">Last marked helpful: ${new Date(group.lastHelpfulAt).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}.${reasons.length?' Shared selections: '+reasons.map(esc).join(', ')+'.':''} Intensity is within one point of your current selection (${intensity}/5).</p>${group.lastHelpfulNote?`<details><summary>Your saved note from that moment</summary><p class="checkin-note">${esc(group.lastHelpfulNote)}</p></details>`:''}${action}<button class="text-btn" data-memory-evidence="${esc(group.id)}">View the ${group.rated} matching ${group.rated===1?'log':'logs'}</button></div>`}
function pastHelpPanel(compact=false){memoryGroupCache.clear();const results=memoryResults(compact);return `<section class="past-help"><div class="section-head"><h2>Pichhli baar kya helped?</h2></div>${results.length?results.slice(0,compact?1:6).map(memoryCard).join(''):`<div class="panel"><h3>${checkins.length?'No close, rated match yet.':'Abhi tumhari history ban rahi hai.'}</h3><p>${checkins.length?'There isn’t a matching saved action marked helpful with these choices. We won’t call an unrelated entry a similar moment.':'When you choose to save what you tried and whether it helped, you can find it here later.'}</p></div>`}<p class="small">A memory of your own feedback—not a prediction that it will help today. Unknown ratings aren’t counted. No note is sent to AI.</p>${button(memoryAlternatives?'Hide other paths':'Aaj kuch different try karein','memory-alternatives','secondary')}${memoryAlternatives?`<div class="chips"><button class="chip" data-action="start-reset">Quiet reset</button><button class="chip" data-go="play">Interactive story</button><button class="chip" data-go="passages">A different reading</button></div>`:''}${compact?'<a class="text-btn" href="#memory">Change the feeling, need, or context filter</a>':''}</section>`}
function memoryView(){return `${button('‹ My month','go-month','back')}<h1>What helped last time?</h1><p class="sub">Tumhare apne moments. Aaj ki choice phir bhi tumhari.</p><label class="field" for="memory-mood">Find moments with this feeling</label><select id="memory-mood" class="section-select"><option value="current">Use my current feeling choices</option><option value="any" ${memoryMood==='any'?'selected':''}>No feeling comparison</option>${moodData.map(m=>`<option value="${m.id}" ${memoryMood===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select><label class="field" for="memory-need">And / or this need</label><select id="memory-need" class="section-select"><option value="current">Use my current need choice</option>${needOptions(memoryNeed)}</select><label class="field" for="memory-situation">Context <span class="small">(optional)</span></label><select id="memory-situation" class="section-select"><option value="any">Any context</option>${situationChoices.map(([id,label])=>`<option value="${id}" ${memorySituation===id?'selected':''}>${label}</option>`).join('')}</select>${pastHelpPanel()}<p class="note">Similar means a shared selected feeling or need, with intensity within one point. A chosen context must also match. When neither a feeling nor a need is selected, this becomes a view of previous rated moments.</p>`}
function scopedNeedEntries(){const now=new Date();if(needScope==='month')return AntarPatterns.entriesForMonth(checkins,monthKey());if(needScope==='all')return checkins.filter(AntarPatterns.valid);const start=new Date(now);start.setDate(start.getDate()-89);start.setHours(0,0,0,0);return checkins.filter(AntarPatterns.valid).filter(e=>Date.parse(e.at)>=start.getTime()&&Date.parse(e.at)<=now.getTime());}
function needScopeKey(){return needScope==='month'?'month:'+monthKey():needScope;}
function needGroup(need){return AntarMemory.needs(scopedNeedEntries()).groups.find(x=>x.need===need);}
function matchingNeedReview(group){if(!group)return null;const key=AntarMemory.fingerprint(group.need,needScopeKey(),group.fingerprintKeys||group.entryIds);return needReviews.find(r=>r.fingerprint===key);}
function saveNeedReview(need,choice,alternative=''){const group=needGroup(need);if(!group)return;const review={fingerprint:AntarMemory.fingerprint(need,needScopeKey(),group.fingerprintKeys||group.entryIds),need,scope:needScopeKey(),entryIds:group.entryIds,choice,alternative,at:new Date().toISOString()};try{const prior=JSON.parse(localStorage.getItem(NEED_REVIEW_KEY)||'[]');const valid=Array.isArray(prior)?prior.filter(x=>x&&typeof x.fingerprint==='string'):[];const next=[...valid.filter(x=>x.fingerprint!==review.fingerprint),review].slice(-100);localStorage.setItem(NEED_REVIEW_KEY,JSON.stringify(next));needReviews=next;correctingNeed='';render(true);toast(choice==='fits'?'Your confirmation is saved.':'Your correction is saved; old logs are unchanged.')}catch{toast('Your review could not be saved.')}}
function needsMap(){const summary=AntarMemory.needs(scopedNeedEntries());return `${button('‹ My month','go-month','back')}<h1>Meri needs ka map.</h1><p class="sub">Jo tumne khud choose kiya—usko saath dekhte hain.</p><div class="chips">${[['90','Last 90 days'],['month',monthLabel(monthKey())],['all','All saved logs']].map(([id,label])=>`<button class="chip ${needScope===id?'selected':''}" data-need-scope="${id}" aria-pressed="${needScope===id}">${esc(label)}</button>`).join('')}</div><p class="small">${summary.withNeeds} of ${summary.total} logs have a need selected. Empty need fields stay unknown. These bars show mentions, not your personality or a diagnosis.</p><div class="needs-map">${careNeeds.map(([id,label,h])=>{const group=summary.groups.find(g=>g.need===id),review=matchingNeedReview(group);return `<article class="need-tile"><h3>${esc(label)}</h3>${hi(h)}<div class="need-bar" aria-hidden="true"><span style="width:${group&&summary.withNeeds?Math.round(group.count/summary.withNeeds*100):0}%"></span></div><p>${group?`${group.count} ${group.count===1?'mention':'mentions'} · ${group.days} ${group.days===1?'day':'days'}`:'No recorded mention'}</p>${group?.recurring?'<p class="small">Came up on at least 3 separate logged days. Worth exploring, if it fits.</p>':group?'<p class="small">A small observation so far; not a recurring pattern.</p>':''}${group?`${review?`<p class="review-status">${review.choice==='fits'?'You said this observation fits.':'You felt '+esc(needLabel(review.alternative))+' fits this observation better.'}</p>`:''}<div class="need-review-actions"><button class="text-btn" data-review-need="${id}">Haan, fits</button><button class="text-btn" data-correct-need="${id}">Not quite</button></div>${correctingNeed===id?`<label class="small" for="correct-${id}">What feels closer?</label><select id="correct-${id}" class="section-select">${needOptions('',false)}</select><button class="secondary" data-save-correction="${id}">Save my correction</button><p class="small">This records your interpretation without rewriting old logs. You can edit their need fields separately.</p>`:''}<button class="text-btn" data-need-evidence="${id}">View source logs</button>`:''}</article>`}).join('')}</div><p class="note">Confirmations apply to the exact logs behind an observation. New or edited source logs may need a fresh review. You can change your interpretation at any time.</p>${button('Log a moment with an optional need','new-checkin','secondary')}`}
function activeFilterCount(){return Object.entries(logFilters).filter(([k,v])=>['q','from','to'].includes(k)?!!v.trim():v!=='any').length;}
function logFilterControls(){return `<details class="log-filters" ${activeFilterCount()?'open':''}><summary>Search & filter logs${activeFilterCount()?' · '+activeFilterCount()+' active':''}</summary><label class="field" for="history-search">Search your notes or selections</label><input id="history-search" type="search" value="${esc(logFilters.q)}" placeholder="A word, context, or date…"><div class="filter-pair"><div><label class="field" for="history-from">From</label><input id="history-from" type="date" value="${esc(logFilters.from)}"></div><div><label class="field" for="history-to">To</label><input id="history-to" type="date" value="${esc(logFilters.to)}"></div></div><label class="field" for="filter-mood">Feeling</label><select id="filter-mood" class="section-select"><option value="any">Any feeling</option>${moodData.map(m=>`<option value="${m.id}" ${logFilters.mood===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select><label class="field" for="filter-need">Need</label><select id="filter-need" class="section-select">${needOptions(logFilters.need)}</select><label class="field" for="filter-situation">Context</label><select id="filter-situation" class="section-select"><option value="any">Any context</option>${situationChoices.map(([id,label])=>`<option value="${id}" ${logFilters.situation===id?'selected':''}>${label}</option>`).join('')}</select><label class="field" for="filter-outcome">Helpfulness feedback</label><select id="filter-outcome" class="section-select">${[['any','Any feedback'],['helped','Marked helpful'],['not-helped','Marked not helpful'],['unsure','Unknown / not rated']].map(([id,label])=>`<option value="${id}" ${logFilters.outcome===id?'selected':''}>${label}</option>`).join('')}</select>${button('Clear search and filters','reset-log-filters','text-btn')}</details>`}
function logRows(records){return records.map(e=>`<article class="checkin-row"><div class="inline-row"><strong>${new Date(e.at).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})} · ${new Date(e.at).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}</strong><span class="small">${e.intensity}/5${e.durationKnown?' · ~'+e.minutes+' min':''}</span></div><p>${e.moods.map(id=>esc(moodData.find(m=>m.id===id)?.name||id)).join(' + ')}</p><p class="small">${esc(nameFor(situationChoices,e.situation))}${e.need?' · Need: '+esc(needLabel(e.need)):''}${e.activity?' · '+esc(nameFor(activityChoices,e.activity)):''}${e.activity&&e.outcome!=='unsure'?' · '+(e.outcome==='helped'?'marked helpful':'marked not helpful'):''}</p>${e.activityDetail?`<p class="small">${esc(e.activityDetail)}</p>`:''}${e.excerptId?`<a class="text-btn" href="#excerpt/${encodeURIComponent(e.excerptId)}">${esc(excerptBank?.find(p=>p.id===e.excerptId)?.heading||'View the passage')}</a>`:''}${e.note?`<p class="checkin-note">${esc(e.note)}</p>`:''}<div class="passage-actions"><button class="text-btn" data-edit-checkin="${esc(e.id)}">Edit</button><button class="text-btn" data-delete-checkin="${esc(e.id)}">Remove</button></div></article>`).join('');}
function filteredHistory(){let entries=checkins;if(route==='month')entries=AntarPatterns.entriesForMonth(entries,monthKey()).filter(e=>!monthDay||AntarPatterns.dateKey(new Date(e.at))===monthDay);else if(historyEvidenceIds)entries=entries.filter(e=>historyEvidenceIds.includes(e.id));return AntarMemory.filterLogs(entries,logFilters);}
function logResultsHTML(){const all=filteredHistory();return `<p class="small" role="status">${all.length} matching ${all.length===1?'log':'logs'}${route==='month'?' in this calendar view':' across saved history'}${historyEvidenceIds&&route==='history'?' · source-evidence view':''}.</p>${logFilters.from&&logFilters.to&&logFilters.from>logFilters.to?'<p class="warning">The “From” date is after “To.” Adjust the range.</p>':''}${all.length?logRows(all.slice(0,historyLimit)):'<p class="empty">No saved logs in this view. Missing entries don’t tell us how a day felt.</p>'}${all.length>historyLimit?button('Show 30 more ('+Math.min(historyLimit,all.length)+' of '+all.length+' shown)','more-history','secondary'):''}${monthDay&&route==='month'?button('Add a log for this day','log-selected-day','secondary'):''}`}
function updateLogResults(){const target=$('#log-results');if(target)target.innerHTML=logResultsHTML();}
function historyPrivacy(){return `${lastDeletedCheckin?button('Undo last removal','undo-checkin','secondary'):''}<details><summary>Data, exports & privacy</summary><p class="small">Logs and needs-map reviews are stored in this browser/device, without app encryption or account sync. Nothing here is sent to AI. Exports contain your personal notes; keep them somewhere private.</p>${button('Download my complete history','export-checkins','secondary')}${button('Delete all saved check-ins','delete-checkins','text-btn')}${checkinReadError?'<p class="warning">History could not be read. Export the original raw data before clearing it if you want to retain it.</p>':''}</details>`}
function fullHistory(){return `${button('‹ My month','go-month','back')}<div class="section-head"><h1>All my logs.</h1>${button('+ A moment','new-checkin','small-add')}</div><p class="sub">Saare saved moments, ek jagah. Across every month.</p>${historyEvidenceIds?`<div class="panel"><p>Showing the specific source logs behind the observation you opened.</p>${button('Show all saved logs','show-all-history','text-btn')}</div>`:''}${logFilterControls()}<div id="log-results">${logResultsHTML()}</div>${historyPrivacy()}`}
function monthView(){const key=monthKey(),summary=AntarPatterns.summarize(checkins,key),filtered=AntarMemory.filterLogs(summary.records,logFilters);return `<div class="section-head"><h1>Mera calendar.</h1>${button('+ A moment','new-checkin','small-add')}</div><p class="sub">Har saved log tak pahunch. Tumhari pace par.</p><div class="calendar-tabs"><span aria-current="page">Calendar</span><a href="#history">All logs</a><a href="#needs">Needs map</a></div><div class="month-controls"><button data-month-shift="-1" aria-label="Previous month">‹</button><label for="calendar-month" class="visually-hidden">Choose month</label><input id="calendar-month" type="month" value="${key}" max="${AntarPatterns.dateKey(new Date()).slice(0,7)}"><button data-month-shift="1" aria-label="Next month" ${monthOffset>=0?'disabled':''}>›</button></div><div class="month-stats"><div><strong>${summary.loggedDays}</strong><span>days with entries</span></div><div><strong>${summary.records.length}</strong><span>saved logs this month</span></div><div><strong>${summary.durationCount?summary.knownMinutes+'m':'—'}</strong><span>known estimated duration</span></div></div>${logFilterControls()}${calendarHTML(key,filtered)}${activeFilterCount()?`<p class="small">Calendar dots show ${filtered.length} matched logs of ${summary.records.length} this month. Month totals and observations use the complete month.</p>`:''}<section id="day-log-list"><div class="section-head"><h2>${monthDay?'Logs for '+monthDay:'This month’s logs'}</h2>${monthDay?button('Whole month','clear-day','text-btn'):''}</div><div id="log-results">${logResultsHTML()}</div></section><div class="home-shortcuts"><a href="#memory"><span>↺</span><strong>What helped last time?</strong><small>Your rated actions</small></a><a href="#needs"><span>◌</span><strong>My needs map</strong><small>Confirm what fits</small></a></div><details><summary>Observations & within-month rhythm</summary>${patternInsights(summary)}${summary.thirds.map(x=>`<div class="phase-row"><span>${x.label}</span><span>${x.difficultDays} days with difficult moments / ${x.loggedDays} logged days</span></div>`).join('')}${summary.cycleObservations.map(x=>`<div class="pattern-insight"><h3>A repeated logging cluster</h3><p>${x.label} had the largest count of saved difficult-moment days in ${x.months.length} observed months: ${x.days} days in total.</p><p class="small">A logging pattern, not a mood prediction or evidence about unrecorded days.</p></div>`).join('')}<p class="note">One month cannot establish a repeating cycle. You have ${summary.observedMonths} months with at least 6 logged days. These are calendar portions, not biological phases.</p></details><label class="field"><input id="learning-toggle" type="checkbox" ${personalLearning?'checked':''}>Use my saved helpfulness feedback for passage suggestions</label>${historyPrivacy()}`}
function showEvidence(ids){historyEvidenceIds=[...ids];logFilters={mood:'any',need:'any',situation:'any',outcome:'any',q:'',from:'',to:''};historyLimit=30;go('history');}
document.addEventListener('input',e=>{if(e.target.id==='history-search'){logFilters.q=e.target.value;historyLimit=30;updateLogResults()}});
document.addEventListener('change',e=>{const fields={'filter-mood':'mood','filter-need':'need','filter-situation':'situation','filter-outcome':'outcome','history-from':'from','history-to':'to'};if(fields[e.target.id]){logFilters[fields[e.target.id]]=e.target.value;historyLimit=30;render(true);return}if(e.target.id==='calendar-month'){const [y,m]=e.target.value.split('-').map(Number),now=new Date();if(y&&m){monthOffset=Math.min(0,(y-now.getFullYear())*12+m-now.getMonth()-1);monthDay='';historyLimit=30;render()}}if(e.target.id==='log-need'&&logDraft)logDraft.need=e.target.value;if(e.target.id==='memory-mood'){memoryMood=e.target.value;render(true)}if(e.target.id==='memory-need'){memoryNeed=e.target.value;render(true)}if(e.target.id==='memory-situation'){memorySituation=e.target.value;render(true)}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.needScope){needScope=el.dataset.needScope;correctingNeed='';render(true);return}if(el.dataset.reviewNeed){saveNeedReview(el.dataset.reviewNeed,'fits');return}if(el.dataset.correctNeed){correctingNeed=correctingNeed===el.dataset.correctNeed?'':el.dataset.correctNeed;render(true);return}if(el.dataset.saveCorrection){const id=el.dataset.saveCorrection,alternative=$('#correct-'+id).value;if(!alternative)return toast('Choose what feels closer, or leave it open.');saveNeedReview(id,'corrected',alternative);return}if(el.dataset.needEvidence){const g=needGroup(el.dataset.needEvidence);if(g)showEvidence(g.entryIds);return}if(el.dataset.memoryEvidence){const group=memoryGroupCache.get(el.dataset.memoryEvidence);if(group)showEvidence(group.entryIds);return}if(el.dataset.keepMemory){const group=memoryGroupCache.get(el.dataset.keepMemory);if(group)saveAnchor('Something I marked helpful before: '+(group.activityDetail||nameFor(activityChoices,group.activity))+'. I can choose whether it fits today.');return}if(el.dataset.monthDay){$('#day-log-list')?.scrollIntoView({block:'start'});return}const a=el.dataset.action;if(a==='memory-alternatives'){memoryAlternatives=!memoryAlternatives;render(true)}if(a==='more-history'){historyLimit+=30;updateLogResults()}if(a==='reset-log-filters'){logFilters={mood:'any',need:'any',situation:'any',outcome:'any',q:'',from:'',to:''};historyLimit=30;render(true)}if(a==='show-all-history'){historyEvidenceIds=null;logFilters={mood:'any',need:'any',situation:'any',outcome:'any',q:'',from:'',to:''};historyLimit=30;render()}if(a==='log-selected-day'&&monthDay){const day=monthDay;beginCheckin();if(day!==AntarPatterns.dateKey(new Date()))logDraft.at=day+'T12:00';render()}});
window.addEventListener('storage',event=>{if(event.key===CHECKIN_KEY||event.key===null){try{const data=JSON.parse(localStorage.getItem(CHECKIN_KEY)||'[]');if(!Array.isArray(data)||!data.every(AntarPatterns.valid))throw Error();checkins=data;checkinReadError=false;}catch{checkinReadError=true;}if(['month','history','needs','memory','support'].includes(route))render(true)}if(event.key===NEED_REVIEW_KEY){try{const r=JSON.parse(localStorage.getItem(NEED_REVIEW_KEY)||'[]');needReviews=Array.isArray(r)?r.filter(x=>x&&typeof x.fingerprint==='string'):[];}catch{}if(route==='needs')render(true)}});
